export class Webhooks {
  /**
   * List Webhooks
   *
   * List every active webhook for the authenticated project. The signing secret is never included.
   */
  public static listWebhooks<ThrowOnError extends boolean = true>(
    options?: Options<ListWebhooksData, ThrowOnError>,
  ): RequestResult<ListWebhooksResponses, ListWebhooksErrors, ThrowOnError, 'data'> {
    return (options?.client ?? client).get<ListWebhooksResponses, ListWebhooksErrors, ThrowOnError, 'data'>({
      responseStyle: 'data',
      security: [{ name: 'anchor-api-key', type: 'apiKey' }],
      url: '/v1/webhooks',
      ...options,
    });
  }

  /**
   * Create Webhook
   *
   * Register a new HTTPS endpoint to receive events. The response includes
   * a one-time `secret` (HMAC-SHA256 signing key) — store it; Anchor never
   * returns it again. Up to 5 webhooks per project.
   *
   */
  public static createWebhook<ThrowOnError extends boolean = true>(
    options: Options<CreateWebhookData, ThrowOnError>,
  ): RequestResult<CreateWebhookResponses, CreateWebhookErrors, ThrowOnError, 'data'> {
    return (options.client ?? client).post<CreateWebhookResponses, CreateWebhookErrors, ThrowOnError, 'data'>(
      {
        responseStyle: 'data',
        security: [{ name: 'anchor-api-key', type: 'apiKey' }],
        url: '/v1/webhooks',
        ...options,
        headers: {
          'Content-Type': 'application/json',
          ...options.headers,
        },
      },
    );
  }

  /**
   * Delete Webhook
   *
   * Soft-delete a webhook. New events stop fanning out immediately. The events
   * history (`/v1/webhooks/{id}/events`) is still queryable for the retention
   * window even after delete.
   *
   */
  public static deleteWebhook<ThrowOnError extends boolean = true>(
    options: Options<DeleteWebhookData, ThrowOnError>,
  ): RequestResult<DeleteWebhookResponses, DeleteWebhookErrors, ThrowOnError, 'data'> {
    return (options.client ?? client).delete<
      DeleteWebhookResponses,
      DeleteWebhookErrors,
      ThrowOnError,
      'data'
    >({
      responseStyle: 'data',
      security: [{ name: 'anchor-api-key', type: 'apiKey' }],
      url: '/v1/webhooks/{id}',
      ...options,
    });
  }

  /**
   * Get Webhook
   *
   * Fetch a single webhook config. The signing secret is never returned.
   */
  public static getWebhook<ThrowOnError extends boolean = true>(
    options: Options<GetWebhookData, ThrowOnError>,
  ): RequestResult<GetWebhookResponses, GetWebhookErrors, ThrowOnError, 'data'> {
    return (options.client ?? client).get<GetWebhookResponses, GetWebhookErrors, ThrowOnError, 'data'>({
      responseStyle: 'data',
      security: [{ name: 'anchor-api-key', type: 'apiKey' }],
      url: '/v1/webhooks/{id}',
      ...options,
    });
  }

  /**
   * Update Webhook
   *
   * Partial update — pass only the fields you want to change. Setting `enabled: false`
   * immediately stops events from fanning out to this webhook (existing in-flight
   * deliveries finish their attempts).
   *
   */
  public static updateWebhook<ThrowOnError extends boolean = true>(
    options: Options<UpdateWebhookData, ThrowOnError>,
  ): RequestResult<UpdateWebhookResponses, UpdateWebhookErrors, ThrowOnError, 'data'> {
    return (options.client ?? client).patch<
      UpdateWebhookResponses,
      UpdateWebhookErrors,
      ThrowOnError,
      'data'
    >({
      responseStyle: 'data',
      security: [{ name: 'anchor-api-key', type: 'apiKey' }],
      url: '/v1/webhooks/{id}',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Rotate Webhook Signing Secret
   *
   * Mint a new HMAC-SHA256 signing secret. The previous secret remains valid
   * for 24 hours so you can update your verification code at your own pace,
   * then drop the old secret.
   *
   * The new secret is returned exactly once, in the `secret` field.
   *
   */
  public static rotateWebhookSecret<ThrowOnError extends boolean = true>(
    options: Options<RotateWebhookSecretData, ThrowOnError>,
  ): RequestResult<RotateWebhookSecretResponses, RotateWebhookSecretErrors, ThrowOnError, 'data'> {
    return (options.client ?? client).post<
      RotateWebhookSecretResponses,
      RotateWebhookSecretErrors,
      ThrowOnError,
      'data'
    >({
      responseStyle: 'data',
      security: [{ name: 'anchor-api-key', type: 'apiKey' }],
      url: '/v1/webhooks/{id}/rotate-secret',
      ...options,
    });
  }

  /**
   * Send Test Event
   *
   * Fire a synthetic event of the given type through the real signing + retry
   * path. Useful during development for confirming your endpoint can verify
   * the signature and is reachable from Anchor's egress IPs.
   *
   * The synthetic delivery counts toward your delivery log so you can see it
   * in `GET /v1/webhooks/{id}/events`.
   *
   */
  public static sendWebhookTestEvent<ThrowOnError extends boolean = true>(
    options: Options<SendWebhookTestEventData, ThrowOnError>,
  ): RequestResult<SendWebhookTestEventResponses, SendWebhookTestEventErrors, ThrowOnError, 'data'> {
    return (options.client ?? client).post<
      SendWebhookTestEventResponses,
      SendWebhookTestEventErrors,
      ThrowOnError,
      'data'
    >({
      responseStyle: 'data',
      security: [{ name: 'anchor-api-key', type: 'apiKey' }],
      url: '/v1/webhooks/{id}/test',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * List Webhook Deliveries
   *
   * Paginated history of every delivery attempt for this webhook (succeeded,
   * failed, or dead-lettered). Filter by status, event type, or time range.
   * Retention: 7 days.
   *
   */
  public static listWebhookEvents<ThrowOnError extends boolean = true>(
    options: Options<ListWebhookEventsData, ThrowOnError>,
  ): RequestResult<ListWebhookEventsResponses, ListWebhookEventsErrors, ThrowOnError, 'data'> {
    return (options.client ?? client).get<
      ListWebhookEventsResponses,
      ListWebhookEventsErrors,
      ThrowOnError,
      'data'
    >({
      responseStyle: 'data',
      security: [{ name: 'anchor-api-key', type: 'apiKey' }],
      url: '/v1/webhooks/{id}/events',
      ...options,
    });
  }
}
